import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Tree","description":"","frontmatter":{},"headers":[],"relativePath":"components/tree.md","filePath":"components/tree.md"}'),d={name:"components/tree.md"};function n(s,e,h,i,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="tree" tabindex="-1">Tree <a class="header-anchor" href="#tree" aria-label="Permalink to &quot;Tree&quot;">​</a></h1><p>Tree is a list with depth: rows that open and close, and that can be reordered by dragging.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for things that contain other things, such as the contents of a document in a <a href="./panel">Panel</a>. It holds <a href="./tree-row">TreeRow</a> and <a href="./drop-line">DropLine</a> only. Pass <code>flat</code> for a list where no row opens. To reorder by dragging, put the <a href="./sortable">sortable</a> action on the elements that hold the rows. Items of one kind that neither nest nor move are a <a href="./list">List</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td></td><td>The name of the tree</td></tr><tr><td><code>flat</code></td><td><code>false</code></td><td>No row opens: no room for the chevron</td></tr><tr><td><code>rows</code></td><td></td><td>The least height of every row: <code>mark</code>, <code>box</code>, <code>thumb</code> or <code>two</code></td></tr><tr><td><code>children</code></td><td>required</td><td>The rows</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The rows touch; the tree&#39;s outline is the edges of its rows, and the distance to what is around it belongs to the Stack it is in. The depth of a row is its own <code>depth</code>, so the elements between the tree and its rows may be flat, or nested in groups that are reordered separately; a group needs no distance of its own. In a <code>flat</code> tree the rows keep no room for the chevron, so their text starts where the head of a <a href="./section-header">SectionHeader</a> does. A row takes its height from its content; <code>rows</code> raises the least height of every row to the height of a list item with a mark, a control, a thumbnail or two lines, so that rows with different content are the same height.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/tree/" title="Tree" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/tree/" target="_blank" rel="noopener">Tree</a></figcaption></figure>',10)])])}const m=t(d,[["render",n]]);export{f as __pageData,m as default};
